#include <curl/curl.h>
#include <stdio.h>

int main(void) {
  curl_global_init(CURL_GLOBAL_DEFAULT);
  CURL *h = curl_easy_init();
  curl_easy_setopt(h, CURLOPT_URL, "https://example.com/");
  curl_easy_setopt(h, CURLOPT_FOLLOWLOCATION, 1L);   /* like -L */
  curl_easy_setopt(h, CURLOPT_TIMEOUT, 20L);         /* like --max-time 20 */
  CURLcode rc = curl_easy_perform(h);                /* body -> stdout */
  long code = 0;
  curl_easy_getinfo(h, CURLINFO_RESPONSE_CODE, &code);
  fprintf(stderr, "rc=%d http=%ld\n", (int)rc, code);  /* rc=0 http=200 */
  curl_easy_cleanup(h);
  curl_global_cleanup();
  return rc != CURLE_OK;
}
/* build: cc get.c -lcurl   |  generate similar code: curl -L --libcurl get.c URL */
